#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""Scorer for the fastbox kit. usage: python3 -I fb_table.py <OUT_BASE>
Reads every <window>_<threads>/results.csv under OUT_BASE; stdlib only."""
import csv, os, re, statistics as st, sys

DEFAULT_END = {"heavy": int(os.environ.get("END_HEAVY", 3105444)), "small": int(os.environ.get("END_SMALL", 3106800))}
METRICS = ["cpu_s", "wall_s", "peak_anon_MB", "post_idle_anon_MB", "blocks", "cpu_per_block", "peer_cpu_s"]
CHANGES = ["cpu_s", "wall_s", "peak_anon_MB", "cpu_per_block"]


def num(x):
    try:
        return float(x)
    except (TypeError, ValueError):
        return None


def stat(vals):
    vals = [v for v in vals if v is not None]
    return (st.median(vals), min(vals), max(vals)) if vals else None


def fmt(s, d=1):
    return "n/a" if s is None else f"{s[0]:.{d}f} ({s[1]:.{d}f}-{s[2]:.{d}f})"


def dir_key(name):
    w, _, t = name.partition("_")
    return (0 if w == "heavy" else 1 if w == "small" else 2, w, -1 if t == "default" else int(t) if t.isdigit() else 10**9, t)


def load(path):
    p = os.path.join(path, "results.csv")
    if not os.path.isfile(p):
        return None
    try:
        with open(p, newline="") as f:
            return list(csv.DictReader(f))
    except (OSError, csv.Error):
        return None


def end_for(path, name):
    try:
        with open(os.path.join(path, "summary.txt")) as f:
            m = re.search(r"\bend=(\d+)", f.readline())
            if m:
                return int(m.group(1))
    except OSError:
        pass
    return DEFAULT_END.get(name.partition("_")[0])


def complete(path):
    try:
        with open(os.path.join(path, "summary.txt")) as f:
            lines = f.read().splitlines()
        return "complete" if lines and lines[-1] == "AB_COMPLETE" else "partial (no AB_COMPLETE)"
    except OSError:
        return "no summary.txt"


def analyse(base, name):
    path = os.path.join(base, name)
    rows = load(path)
    res = {"name": name, "status": complete(path), "rows": rows or [], "end": end_for(path, name)}
    per = {}
    for r in res["rows"]:
        cpu, blk = num(r.get("cpu_s")), num(r.get("blocks"))
        r["_m"] = {"cpu_s": cpu, "wall_s": num(r.get("wall_s")), "peak_anon_MB": num(r.get("peak_anon_MB")),
                   "post_idle_anon_MB": num(r.get("post_idle_anon_MB")), "blocks": blk, "peer_cpu_s": num(r.get("peer_cpu_s")),
                   "cpu_per_block": cpu / blk if cpu is not None and blk else None}
        per.setdefault(r.get("arm", "?"), []).append(r)
    res["arms"] = {a: {m: stat([r["_m"][m] for r in rs]) for m in METRICS} for a, rs in per.items()}
    res["n"] = {a: len(rs) for a, rs in per.items()}
    res["hash_yes"] = sum(1 for r in res["rows"] if r.get("hash_match") == "yes")
    inc = []
    for r in res["rows"]:
        e = num(r.get("end_h"))
        if res["end"] is not None and (e is None or e < res["end"]):
            inc.append(f"r{r.get('round')}_{r.get('arm')} end_h={r.get('end_h') or '?'}")
    res["incomplete"] = inc
    ch = {}
    s, e = res["arms"].get("S"), res["arms"].get("E")
    for m in CHANGES:
        if s and e and s[m] and e[m] and s[m][0]:
            pct = (e[m][0] - s[m][0]) / s[m][0] * 100
            tag = "disjoint" if e[m][2] < s[m][1] or e[m][1] > s[m][2] else "overlap"
            ch[m] = (pct, tag)
    res["changes"] = ch
    return res


def chg(res, m):
    c = res["changes"].get(m)
    return "n/a" if c is None else f"{c[0]:+.1f}% {c[1]}"


def main():
    if len(sys.argv) != 2 or not os.path.isdir(sys.argv[1]):
        print("usage: python3 -I fb_table.py <OUT_BASE>", file=sys.stderr)
        return 2
    base = sys.argv[1]
    names = sorted((d for d in os.listdir(base) if os.path.isdir(os.path.join(base, d)) and re.match(r"^(heavy|small)_", d)), key=dir_key)
    if not names:
        print("no <window>_<threads> dirs found")
    results = [analyse(base, n) for n in names]
    for r in results:
        print(f"== {r['name']}  END={r['end']}  runs={len(r['rows'])}  {r['status']}")
        if not r["rows"]:
            print("   no results rows")
            continue
        print(f"   {'arm':<4}{'n':>2}  " + "  ".join(f"{m:<26}" for m in METRICS))
        for a in sorted(r["arms"]):
            print(f"   {a:<4}{r['n'][a]:>2}  " + "  ".join(f"{fmt(r['arms'][a][m], 3 if m == 'cpu_per_block' else 1):<26}" for m in METRICS))
        print("   E vs S: " + "; ".join(f"{m} {chg(r, m)}" for m in CHANGES))
        print(f"   hash_match yes: {r['hash_yes']}/{len(r['rows'])}")
        if r["incomplete"]:
            print("   incomplete: " + ", ".join(r["incomplete"]))
    print("\n=== SUMMARY (E vs S, % change of medians; disjoint = ranges do not overlap) ===")
    print(f"{'dir':<16}{'runs':>5} {'hash':>6} {'incompl':>8}  " + "  ".join(f"{m:<20}" for m in CHANGES))
    th = tr = ti = 0
    for r in results:
        n = len(r["rows"]); th += r["hash_yes"]; tr += n; ti += len(r["incomplete"])
        print(f"{r['name']:<16}{n:>5} {str(r['hash_yes']) + '/' + str(n):>6} {len(r['incomplete']):>8}  " + "  ".join(f"{chg(r, m):<20}" for m in CHANGES))
    print(f"TOTAL runs={tr} hash_match yes={th}/{tr} incomplete={ti}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
